#include "dblyat/win32_kernel32_gateway.h"
#include <stdint.h>
#include <unistd.h>
#define CHECK(v) do { if (!(v)) return 0; } while (0)
static void fill(void *p,size_t n,uint8_t v){uint8_t*b=p;size_t i;for(i=0u;i<n;++i)b[i]=v;}
static int same(const void*a,const void*b,size_t n){const uint8_t*x=a,*y=b;size_t i;for(i=0u;i<n;++i)if(x[i]!=y[i])return 0;return 1;}
static void request(db_gateway_invoke_request*r,uint32_t symbol,uint32_t handler,size_t count){fill(r,sizeof(*r),0u);r->rip=UINT64_C(0x10040);r->slot_address=r->rip;r->guest_rsp=UINT64_C(0x70000010);r->return_address=UINT64_C(0x401000);r->slot_index=1u;r->argument_count=count;r->provider_id=DB_WIN32_PROVIDER_KERNEL32;r->symbol_id=symbol;r->handler_id=handler;}
static db_gateway_x64_guest_state guest(const db_gateway_invoke_request*r){db_gateway_x64_guest_state s;fill(&s,sizeof(s),0u);s.rax=7u;s.rbx=8u;s.rsp=r->guest_rsp;s.rip=r->rip;return s;}
static int preserved(db_gateway_invoke_request*r,db_win32_kernel32_state*p,db_gateway_x64_guest_state*g,db_win32_kernel32_gateway_status expected){db_win32_kernel32_state pb=*p;db_gateway_x64_guest_state gb=*g;db_win32_kernel32_gateway_summary s,sb;fill(&s,sizeof(s),0xa5);sb=s;CHECK(db_win32_kernel32_gateway_run(r,p,g,&s)==expected);CHECK(same(p,&pb,sizeof(*p)));CHECK(same(g,&gb,sizeof(*g)));CHECK(same(&s,&sb,sizeof(s)));return 1;}
static int success(void){db_gateway_invoke_request r;db_win32_kernel32_state p={10u,20u,5u,0u};db_gateway_x64_guest_state g;db_win32_kernel32_gateway_summary s;request(&r,DB_WIN32_SYMBOL_KERNEL32_SET_LAST_ERROR,DB_WIN32_HANDLER_KERNEL32_SET_LAST_ERROR,1u);r.arguments[0]=99u;g=guest(&r);CHECK(db_win32_kernel32_gateway_run(&r,&p,&g,&s)==DB_WIN32_KERNEL32_GATEWAY_OK);CHECK(p.process_id==10u&&p.thread_id==20u&&p.last_error==99u&&p.reserved==0u);CHECK(g.rax==0u&&g.rsp==r.guest_rsp+8u&&g.rip==r.return_address&&g.rbx==8u);CHECK(s.result.handler_id==r.handler_id&&s.result.raw_result==0u&&s.completion.validated.raw_result==0u&&s.reserved==0u);return 1;}
static int failures(void){db_gateway_invoke_request r;db_win32_kernel32_state p={10u,20u,5u,0u};db_gateway_x64_guest_state g;request(&r,DB_WIN32_SYMBOL_KERNEL32_SET_LAST_ERROR,DB_WIN32_HANDLER_KERNEL32_SET_LAST_ERROR,1u);r.arguments[0]=UINT64_C(0x100000000);g=guest(&r);CHECK(preserved(&r,&p,&g,DB_WIN32_KERNEL32_GATEWAY_INVOCATION_FAILED));r.arguments[0]=1u;g=guest(&r);g.rip+=1u;CHECK(preserved(&r,&p,&g,DB_WIN32_KERNEL32_GATEWAY_COMPLETION_FAILED));request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_CURRENT_PROCESS_ID,DB_WIN32_HANDLER_KERNEL32_GET_CURRENT_PROCESS_ID,0u);r.provider_id=9u;g=guest(&r);CHECK(preserved(&r,&p,&g,DB_WIN32_KERNEL32_GATEWAY_INVOCATION_FAILED));return 1;}
static int aliases(void){db_gateway_invoke_request r;db_win32_kernel32_state p={1u,2u,3u,0u};db_gateway_x64_guest_state g;db_win32_kernel32_gateway_summary s;union u{db_gateway_x64_guest_state guest;db_win32_kernel32_gateway_summary summary;}a;request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_LAST_ERROR,DB_WIN32_HANDLER_KERNEL32_GET_LAST_ERROR,0u);g=guest(&r);CHECK(db_win32_kernel32_gateway_run(0,&p,&g,&s)==DB_WIN32_KERNEL32_GATEWAY_NULL_ARGUMENT);CHECK(db_win32_kernel32_gateway_run(&r,&p,&a.guest,&a.summary)==DB_WIN32_KERNEL32_GATEWAY_BUFFER_OVERLAP);return 1;}
int main(void){static const char ok[]="WIN32 KERNEL32 GATEWAY TEST: PASS\n";static const char bad[]="WIN32 KERNEL32 GATEWAY TEST: FAIL\n";if(success()&&failures()&&aliases()){(void)write(STDOUT_FILENO,ok,sizeof(ok)-1u);return 0;}(void)write(STDERR_FILENO,bad,sizeof(bad)-1u);return 1;}
